args.sparql:
SELECT ?entity ?entityLabel ?p ?date WHERE {
  VALUES ?entity { dbr:Penang_Free_School dbr:Universidad_Autonoma_de_La_Laguna }
  OPTIONAL { ?entity rdfs:label ?entityLabel . FILTER(langMatches(lang(?entityLabel), "EN")) }
  VALUES ?p { dbo:established dbp:established dbo:foundingYear dbo:foundingDate dbp:founding dbp:foundingYear }
  ?entity ?p ?date .
} ORDER BY ?entity ?p

SELECT ?entity ?label ?est1 ?est2 ?foundYear WHERE {
  VALUES ?entity { dbr:Penang_Free_School dbr:Universidad_Autonoma_de_La_Laguna }
  OPTIONAL { ?entity rdfs:label ?label . FILTER(langMatches(lang(?label), "EN")) }
  OPTIONAL { ?entity dbp:established ?est1 }
  OPTIONAL { ?entity dbo:established ?est2 }
  OPTIONAL { ?entity dbo:foundingYear ?foundYear }
} ORDER BY ?entity

SELECT ?entity ?date WHERE {
  VALUES ?entity { dbr:Penang_Free_School dbr:Universidad_Autonoma_de_La_Laguna }
  OPTIONAL { ?entity dbp:established ?date }
} ORDER BY ?entity

